294→  test('TC06: sidebar navigation to bin page works', async () => {
295→    // Navigate to bin via sidebar
296→    await binPage.navigate();
297→
298→    // Verify URL contains #/bin
299→    expect(page.url()).toContain('#/bin');
300→
301→    // Verify we see either the bin list or the empty state
302→    const hasList = await binPage
303→      .binList()
304→      .isVisible()
305→      .catch(() => false);
306→    const hasEmpty = await binPage
307→      .emptyState()
308→      .isVisible()
309→      .catch(() => false);
310→    expect(hasList || hasEmpty).toBe(true);
