317→  test('TC07: permanent delete reclaims storage without crash', async () => {
318→    test.slow();
319→
320→    const fileName = `bin-perm-${runId}.txt`;
321→    const fileContent = 'x'.repeat(1024); // 1KB file for measurable quota change
322→
323→    // Navigate to files and upload a test file
324→    await navigateToFiles();
325→    const testFile = createTestTextFile(fileName, fileContent);
326→    await uploadZone.uploadFile(testFile.path);
327→    await fileList.waitForItemToAppear(fileName, { timeout: 60000 });
328→
329→    // Wait for upload to fully propagate
330→    await page.waitForTimeout(3000);
331→
332→    // Delete the file (soft-delete -> bin)
333→    await fileList.rightClickItem(fileName);
334→    await contextMenu.waitForOpen();
