258→// Public API: addManyToBin
259→// ---------------------------------------------------------------------------
260→
261→/**
262→ * Add multiple deleted items to the recycle bin in a single IPNS publish.
263→ *
264→ * Unlike calling addToBin in a loop (which publishes per-item), this batches
265→ * all entries into one metadata update.
266→ */
267→export async function addManyToBin(params: {
268→  items: FolderChild[];
269→  parentIpnsName: string;
270→  parentPath: string;
271→  userPublicKey: Uint8Array;
272→  userPrivateKey: Uint8Array;
273→  folderKey?: Uint8Array;
274→}): Promise<void> {
275→  const { items, parentIpnsName, parentPath, userPublicKey, userPrivateKey, folderKey } = params;
276→  if (items.length === 0) return;
277→
278→  const now = Date.now();
279→  const newEntries: BinEntry[] = [];
280→  for (const item of items) {
281→    const isFile = item.type === 'file';
282→    const entry: BinEntry = {
283→      id: crypto.randomUUID(),
284→      itemType: isFile ? 'file' : 'folder',
285→      name: item.name,
286→      originalParentIpnsName: parentIpnsName,
287→      originalPath: parentPath,
288→      deletedAt: now,
289→      size: 0,
290→      mimeType: '',
291→      filePointer: isFile ? (item as FilePointer) : undefined,
292→      folderEntry: !isFile ? (item as FolderEntry) : undefined,
293→    };
294→
295→    // Resolve file CID+size at soft-delete time (when folderKey is available)
296→    if (isFile && folderKey) {
297→      try {
298→        const fp = item as FilePointer;
299→        const resolved = await resolveIpnsRecord(fp.fileMetaIpnsName);
300→        if (resolved?.cid) {
301→          const metaBytes = await fetchFromIpfs(resolved.cid);
302→          const metaJson = new TextDecoder().decode(metaBytes);
303→          const encrypted = JSON.parse(metaJson) as EncryptedFileMetadata;
304→          const fileMeta = await decryptFileMetadata(encrypted, folderKey);
305→          entry.contentCid = fileMeta.cid;
306→          entry.contentSize = fileMeta.size;
307→        }
308→      } catch (err) {
309→        console.warn('[Bin] Failed to resolve file CID for bin entry (non-blocking):', err);
310→      }
311→    }
312→
313→    newEntries.push(entry);
314→  }
315→
316→  const store = useBinStore.getState();
317→  const currentEntries = [...store.entries, ...newEntries];
318→  const newSeq = store.sequenceNumber + 1;
319→
320→  const metadata: RecycleBinMetadata = {
321→    version: BIN_METADATA_VERSION,
322→    sequenceNumber: newSeq,
323→    entries: currentEntries,
324→  };
325→
326→  // Non-blocking: folder delete already committed, bin is best-effort
327→  try {
328→    await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
329→    store.setEntries(currentEntries, newSeq);
330→  } catch {
331→    console.error('[Bin] addManyToBin publish failed (non-blocking)');
332→  }
333→}
