531→/**
532→ * Permanently delete multiple bin entries in a single IPNS publish.
533→ *
534→ * Cleans up CIDs for all entries (best-effort), then publishes once.
535→ */
536→export async function permanentlyDeleteBatch(params: {
537→  entryIds: string[];
538→  userPublicKey: Uint8Array;
539→  userPrivateKey: Uint8Array;
540→}): Promise<void> {
541→  const { entryIds, userPublicKey, userPrivateKey } = params;
542→  if (entryIds.length === 0) return;
543→
