642→// ---------------------------------------------------------------------------
643→// Internal helpers
644→// ---------------------------------------------------------------------------
645→
646→/**
647→ * Remove entries from bin metadata and publish the updated metadata.
648→ */
649→async function removeEntriesFromBin(
650→  entryIds: string[],
651→  params: { userPublicKey: Uint8Array; userPrivateKey: Uint8Array }
652→): Promise<void> {
653→  const binStore = useBinStore.getState();
654→  const idsToRemove = new Set(entryIds);
655→  const remainingEntries = binStore.entries.filter((e) => !idsToRemove.has(e.id));
656→  const newSeq = binStore.sequenceNumber + 1;
657→
658→  const metadata: RecycleBinMetadata = {
659→    version: BIN_METADATA_VERSION,
660→    sequenceNumber: newSeq,
661→    entries: remainingEntries,
662→  };
663→
664→  await saveBinMetadata({
665→    metadata,
666→    userPublicKey: params.userPublicKey,
667→    userPrivateKey: params.userPrivateKey,
668→  });
669→
670→  // Update local store (use setEntries with explicit seq to avoid double-increment)
671→  binStore.setEntries(remainingEntries, newSeq);
672→}
673→
674→/**
675→ * Cleanup CIDs for a bin entry (unpin from IPFS + update quota).
676→ *
677→ * Files: use stored contentCid if available, else fall back to IPNS resolution.
678→ * Folders: unwrap folderKey, decrypt folder metadata, decrypt each nested file's
679→ * metadata to get CID for unpinning. Recurses for subfolders.
680→ */
681→async function cleanupEntryCids(entry: BinEntry, userPrivateKey: Uint8Array): Promise<void> {
682→  if (entry.itemType === 'file') {
683→    await unpinFileCids(entry);
684→  } else if (entry.itemType === 'folder' && entry.folderEntry) {
685→    await cleanupFolderCids(entry.folderEntry, userPrivateKey);
686→  }
687→}
688→
689→/**
690→ * Unpin a single file's content and metadata CIDs, and update quota.
691→ *
692→ * Prefers stored contentCid (captured at soft-delete time) to avoid
693→ * re-decrypting encrypted file metadata (which was the GAP-1 bug).
694→ * Falls back to legacy IPNS resolution for old entries without contentCid.
695→ */
696→async function unpinFileCids(entry: BinEntry): Promise<void> {
697→  try {
698→    // Preferred path: use stored contentCid from soft-delete time
699→    if (entry.contentCid) {
700→      await unpinFromIpfs(entry.contentCid);
701→      if (Number.isFinite(entry.contentSize)) {
702→        useQuotaStore.getState().removeUsage(entry.contentSize!);
703→      }
704→      // Also unpin the file metadata CID and any version CIDs
705→      if (entry.filePointer) {
706→        const resolved = await resolveIpnsRecord(entry.filePointer.fileMetaIpnsName);
707→        if (resolved?.cid) {
708→          // Best-effort: try to parse file metadata for version CIDs.
709→          // This uses plaintext JSON parsing — if the metadata is encrypted
710→          // (which it is for v2 entries), version cleanup is skipped here
711→          // but will succeed for folder-nested files in cleanupFolderCids.
712→          try {
713→            const metaBytes = await fetchFromIpfs(resolved.cid);
714→            const metaJson = new TextDecoder().decode(metaBytes);
715→            const fileMeta = JSON.parse(metaJson);
716→            await unpinVersionCids(fileMeta);
717→          } catch {
718→            // Expected for encrypted metadata — version cleanup is best-effort
719→          }
720→          await unpinFromIpfs(resolved.cid).catch(() => {});
721→        }
722→      }
723→      return;
724→    }
725→
726→    // Fallback for legacy entries without contentCid:
727→    // Resolve IPNS and attempt to parse file metadata as plaintext JSON.
728→    // NOTE: This will fail for encrypted file metadata (the original GAP-1 bug).
729→    // Legacy entries that hit this path will log an error but not crash.
730→    if (!entry.filePointer) return;
731→    const fileIpnsName = entry.filePointer.fileMetaIpnsName;
732→    if (!fileIpnsName) return;
733→
734→    const resolved = await resolveIpnsRecord(fileIpnsName);
735→    if (!resolved?.cid) return;
736→
737→    const metaBytes = await fetchFromIpfs(resolved.cid);
738→    const metaJson = new TextDecoder().decode(metaBytes);
739→    const fileMeta = JSON.parse(metaJson);
740→
741→    if (fileMeta.cid) {
742→      await unpinFromIpfs(fileMeta.cid);
743→      if (fileMeta.size && typeof fileMeta.size === 'number') {
744→        useQuotaStore.getState().removeUsage(fileMeta.size);
745→      }
746→    }
747→    await unpinVersionCids(fileMeta);
748→
749→    await unpinFromIpfs(resolved.cid).catch(() => {});
750→  } catch (err) {
751→    console.error(`[Bin] CID cleanup failed for file ${entry.id}:`, err);
752→  }
753→}
