 4→const DEFAULT_LIMIT_BYTES = 500 * 1024 * 1024; // 500 MiB
 5→
 6→const initialState = {
 7→  usedBytes: 0,
 8→  limitBytes: DEFAULT_LIMIT_BYTES,
 9→  remainingBytes: DEFAULT_LIMIT_BYTES,
10→  loading: false,
11→  error: null as string | null,
12→};
13→
14→// Session version guard: incremented on reset() so in-flight fetchQuota()
15→// responses are discarded if they resolve after logout/reset.
16→let quotaSessionVersion = 0;
17→
18→type QuotaState = typeof initialState & {
19→  fetchQuota: () => Promise<void>;
20→  removeUsage: (bytes: number) => void;
21→  canUpload: (bytes: number) => boolean;
22→  reset: () => void;
23→};
24→
25→export const useQuotaStore = create<QuotaState>((set, get) => ({
26→  ...initialState,
27→
28→  fetchQuota: async () => {
29→    const requestVersion = quotaSessionVersion;
30→    set({ loading: true, error: null });
31→    try {
32→      const quota: QuotaResponse = await vaultApi.getQuota();
33→      if (requestVersion !== quotaSessionVersion) return;
34→      set({
35→        usedBytes: quota.usedBytes,
36→        limitBytes: quota.limitBytes,
37→        remainingBytes: quota.remainingBytes,
38→        loading: false,
39→      });
40→    } catch {
41→      if (requestVersion !== quotaSessionVersion) return;
42→      set({ error: 'Failed to fetch quota', loading: false });
43→    }
44→  },
45→
46→  removeUsage: (bytes) =>
47→    set((state) => ({
48→      usedBytes: Math.max(0, state.usedBytes - bytes),
49→      remainingBytes: Math.min(state.limitBytes, state.remainingBytes + bytes),
50→    })),
51→
52→  canUpload: (bytes) => {
53→    const { remainingBytes } = get();
54→    return bytes <= remainingBytes;
55→  },
56→
57→  reset: () => {
58→    quotaSessionVersion += 1;
59→    set(initialState);
60→  },
61→}));
