    13→ */
    14→
    15→import {
    16→  deriveBinIpnsKeypair,
    17→  encryptBinMetadata,
    18→  decryptBinMetadata,
    19→  bytesToHex,
    20→  hexToBytes,
    21→  wrapKey,
    22→  unwrapKey,
    23→  decryptFileMetadata,
    24→  decryptFolderMetadata,
    25→  type RecycleBinMetadata,
    26→  type BinEntry,
    27→  type FolderChild,
    28→  type FilePointer,
    29→  type FolderEntry,
    30→  type EncryptedFileMetadata,
    31→  type EncryptedFolderMetadata,
    32→} from '@cipherbox/crypto';
    33→import { addToIpfs, fetchFromIpfs, unpinFromIpfs } from '../lib/api/ipfs';
    34→import { createAndPublishIpnsRecord, resolveIpnsRecord } from './ipns.service';
    35→import { useAuthStore } from '../stores/auth.store';
    36→import { useBinStore } from '../stores/bin.store';
    37→import { useFolderStore } from '../stores/folder.store';
    38→import { useVaultStore } from '../stores/vault.store';
    39→import { useQuotaStore } from '../stores/quota.store';
    40→import type { FolderNode } from '../stores/folder.store';
    41→
    42→// Track whether TEE enrollment has been done for this session
    43→let binTeeEnrolled = false;
    44→
    45→/** Current bin metadata version. */
    46→const BIN_METADATA_VERSION = 'v1' as const;
    47→
    48→// ---------------------------------------------------------------------------
    49→// Internal helpers: load / save bin metadata
    50→// ---------------------------------------------------------------------------
    51→
    52→/**
    53→ * Load and decrypt bin metadata from IPNS.
    54→ *
    55→ * @returns Decrypted metadata and IPNS resolution data, or null if no bin exists yet
    56→ */
    57→async function loadBinMetadata(params: { userPrivateKey: Uint8Array }): Promise<{
    58→  metadata: RecycleBinMetadata;
    59→  ipnsName: string;
    60→  sequenceNumber: bigint;
    61→} | null> {
    62→  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
    63→  const resolved = await resolveIpnsRecord(binIpns.ipnsName);
    64→
    65→  if (!resolved) {
    66→    return null;
    67→  }
    68→
    69→  const encryptedBytes = await fetchFromIpfs(resolved.cid);
    70→  const metadata = await decryptBinMetadata(encryptedBytes, params.userPrivateKey);
    71→
    72→  return {
    73→    metadata,
    74→    ipnsName: binIpns.ipnsName,
    75→    sequenceNumber: resolved.sequenceNumber,
    76→  };
    77→}
    78→
    79→/**
    80→ * Encrypt and publish bin metadata to IPNS.
    81→ *
    82→ * Handles TEE enrollment on first write.
    83→ */
    84→async function saveBinMetadata(params: {
    85→  metadata: RecycleBinMetadata;
    86→  userPublicKey: Uint8Array;
    87→  userPrivateKey: Uint8Array;
    88→}): Promise<void> {
    89→  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
    90→
    91→  // Encrypt metadata with user's public key (ECIES)
    92→  const encryptedBytes = await encryptBinMetadata(params.metadata, params.userPublicKey);
    93→
    94→  // Pin to IPFS
    95→  const { cid } = await addToIpfs(new Blob([encryptedBytes as BlobPart]));
    96→
    97→  // TEE enrollment on first write (fire-and-forget)
    98→  let encryptedIpnsKey: string | undefined;
    99→  let keyEpoch: number | undefined;
   100→
   101→  const enrollingTee = !binTeeEnrolled;
   102→  if (enrollingTee) {
   103→    const teeKeys = useAuthStore.getState().teeKeys;
   104→    if (teeKeys?.currentPublicKey) {
   105→      try {
   106→        const wrappedKey = await wrapKey(binIpns.privateKey, hexToBytes(teeKeys.currentPublicKey));
   107→        encryptedIpnsKey = bytesToHex(wrappedKey);
   108→        keyEpoch = teeKeys.currentEpoch;
   109→      } catch (err) {
   110→        console.error('[Bin] TEE enrollment failed (non-blocking):', err);
   111→      }
   112→    }
   113→  }
   114→
   115→  // Publish IPNS record
   116→  await createAndPublishIpnsRecord({
   117→    ipnsPrivateKey: binIpns.privateKey,
   118→    ipnsName: binIpns.ipnsName,
   119→    metadataCid: cid,
   120→    sequenceNumber: BigInt(params.metadata.sequenceNumber),
   121→    encryptedIpnsPrivateKey: encryptedIpnsKey,
   122→    keyEpoch,
   123→  });
   124→
   125→  // Mark TEE enrolled only after successful publish
   126→  if (enrollingTee && encryptedIpnsKey) {
   127→    binTeeEnrolled = true;
   128→  }
   129→}
   130→
   131→// ---------------------------------------------------------------------------
   132→// Public API: initializeBin
   133→// ---------------------------------------------------------------------------
   134→
   135→/**
   136→ * Initialize or load the recycle bin on login.
   137→ *
   138→ * Derives the deterministic IPNS keypair, resolves existing bin metadata
   139→ * from IPNS (or creates empty state), and populates the bin store.
   140→ *
   141→ * Non-blocking: errors are logged, not thrown.
   142→ */
   143→export async function initializeBin(params: {
   144→  userPrivateKey: Uint8Array;
   145→  userPublicKey: Uint8Array;
   146→}): Promise<void> {
   147→  const store = useBinStore.getState();
   148→  store.setLoading(true);
   149→
   150→  try {
   151→    // Reset TEE enrollment tracking for new session
   152→    binTeeEnrolled = false;
   153→
   154→    // Try to load existing bin metadata (derives IPNS keypair internally)
   155→    const loaded = await loadBinMetadata({ userPrivateKey: params.userPrivateKey });
   156→
   157→    // Set IPNS name from loaded result, or derive if no bin exists yet
   158→    if (loaded) {
   159→      store.setBinIpnsName(loaded.ipnsName);
   160→    } else {
   161→      const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
   162→      store.setBinIpnsName(binIpns.ipnsName);
   163→    }
   164→
   165→    if (loaded) {
   166→      store.setEntries(loaded.metadata.entries, loaded.metadata.sequenceNumber);
   167→    } else {
   168→      // No bin exists yet -- initialize with empty state
   169→      store.setEntries([], 0);
   170→    }
   171→  } catch (error) {
   172→    console.error('[Bin] Failed to initialize bin:', error);
   173→    store.setError(error instanceof Error ? error.message : 'Failed to initialize bin');
   174→    store.setLoading(false);
   175→  }
   176→}
   177→
   178→// ---------------------------------------------------------------------------
   179→// Public API: addToBin
   180→// ---------------------------------------------------------------------------
   181→
   182→/**
   183→ * Add a deleted item to the recycle bin.
   184→ *
   185→ * Creates a BinEntry from the FolderChild that was removed from its parent,
   186→ * appends it to the bin metadata, encrypts, and publishes.
   187→ *
   188→ * @param params.item - The FolderChild (FilePointer or FolderEntry) that was removed
   189→ * @param params.parentIpnsName - IPNS name of the original parent folder
   190→ * @param params.parentPath - Breadcrumb path at deletion time (e.g., "My Vault / Documents")
   191→ * @param params.userPublicKey - User's secp256k1 public key for ECIES encryption
   192→ * @param params.userPrivateKey - User's secp256k1 private key for IPNS derivation
   193→ */
   194→export async function addToBin(params: {
   195→  item: FolderChild;
   196→  parentIpnsName: string;
   197→  parentPath: string;
   198→  userPublicKey: Uint8Array;
   199→  userPrivateKey: Uint8Array;
   200→  folderKey?: Uint8Array;
   201→}): Promise<void> {
   202→  const { item, parentIpnsName, parentPath, userPublicKey, userPrivateKey, folderKey } = params;
   203→
   204→  // Build bin entry
   205→  const isFile = item.type === 'file';
   206→  const entry: BinEntry = {
   207→    id: crypto.randomUUID(),
   208→    itemType: isFile ? 'file' : 'folder',
   209→    name: item.name,
   210→    originalParentIpnsName: parentIpnsName,
   211→    originalPath: parentPath,
   212→    deletedAt: Date.now(),
   213→    size: 0,
   214→    mimeType: '',
   215→    filePointer: isFile ? (item as FilePointer) : undefined,
   216→    folderEntry: !isFile ? (item as FolderEntry) : undefined,
   217→  };
   218→
   219→  // Resolve file CID+size at soft-delete time (when folderKey is available)
   220→  if (isFile && folderKey) {
   221→    try {
   222→      const fp = item as FilePointer;
   223→      const resolved = await resolveIpnsRecord(fp.fileMetaIpnsName);
   224→      if (resolved?.cid) {
   225→        const metaBytes = await fetchFromIpfs(resolved.cid);
   226→        const metaJson = new TextDecoder().decode(metaBytes);
   227→        const encrypted = JSON.parse(metaJson) as EncryptedFileMetadata;
   228→        const fileMeta = await decryptFileMetadata(encrypted, folderKey);
   229→        entry.contentCid = fileMeta.cid;
   230→        entry.contentSize = fileMeta.size;
   231→      }
   232→    } catch (err) {
   233→      console.warn('[Bin] Failed to resolve file CID for bin entry (non-blocking):', err);
   234→    }
   235→  }
   236→
   237→  // Read current bin state and build updated metadata
   238→  const store = useBinStore.getState();
   239→  const currentEntries = [...store.entries, entry];
   240→  const newSeq = store.sequenceNumber + 1;
   241→
   242→  const metadata: RecycleBinMetadata = {
   243→    version: BIN_METADATA_VERSION,
   244→    sequenceNumber: newSeq,
   245→    entries: currentEntries,
   246→  };
   247→
   248→  // Encrypt and publish (non-blocking: folder delete already committed, bin is best-effort)
   249→  try {
   250→    await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
   251→    store.setEntries(currentEntries, newSeq);
   252→  } catch {
   253→    console.error('[Bin] addToBin publish failed (non-blocking)');
   254→  }
   255→}
   256→
   257→// ---------------------------------------------------------------------------
   258→// Public API: addManyToBin
   259→// ---------------------------------------------------------------------------
   260→
   261→/**
   262→ * Add multiple deleted items to the recycle bin in a single IPNS publish.
   263→ *
   264→ * Unlike calling addToBin in a loop (which publishes per-item), this batches
   265→ * all entries into one metadata update.
   266→ */
   267→export async function addManyToBin(params: {
   268→  items: FolderChild[];
   269→  parentIpnsName: string;
   270→  parentPath: string;
   271→  userPublicKey: Uint8Array;
   272→  userPrivateKey: Uint8Array;
   273→  folderKey?: Uint8Array;
   274→}): Promise<void> {
   275→  const { items, parentIpnsName, parentPath, userPublicKey, userPrivateKey, folderKey } = params;
   276→  if (items.length === 0) return;
   277→
   278→  const now = Date.now();
   279→  const newEntries: BinEntry[] = [];
   280→  for (const item of items) {
   281→    const isFile = item.type === 'file';
   282→    const entry: BinEntry = {
   283→      id: crypto.randomUUID(),
   284→      itemType: isFile ? 'file' : 'folder',
   285→      name: item.name,
   286→      originalParentIpnsName: parentIpnsName,
   287→      originalPath: parentPath,
   288→      deletedAt: now,
   289→      size: 0,
   290→      mimeType: '',
   291→      filePointer: isFile ? (item as FilePointer) : undefined,
   292→      folderEntry: !isFile ? (item as FolderEntry) : undefined,
   293→    };
   294→
   295→    // Resolve file CID+size at soft-delete time (when folderKey is available)
   296→    if (isFile && folderKey) {
   297→      try {
   298→        const fp = item as FilePointer;
   299→        const resolved = await resolveIpnsRecord(fp.fileMetaIpnsName);
   300→        if (resolved?.cid) {
   301→          const metaBytes = await fetchFromIpfs(resolved.cid);
   302→          const metaJson = new TextDecoder().decode(metaBytes);
   303→          const encrypted = JSON.parse(metaJson) as EncryptedFileMetadata;
   304→          const fileMeta = await decryptFileMetadata(encrypted, folderKey);
   305→          entry.contentCid = fileMeta.cid;
   306→          entry.contentSize = fileMeta.size;
   307→        }
   308→      } catch (err) {
   309→        console.warn('[Bin] Failed to resolve file CID for bin entry (non-blocking):', err);
   310→      }
   311→    }
   312→
   313→    newEntries.push(entry);
   314→  }
   315→
   316→  const store = useBinStore.getState();
   317→  const currentEntries = [...store.entries, ...newEntries];
   318→  const newSeq = store.sequenceNumber + 1;
   319→
   320→  const metadata: RecycleBinMetadata = {
   321→    version: BIN_METADATA_VERSION,
   322→    sequenceNumber: newSeq,
   323→    entries: currentEntries,
   324→  };
   325→
   326→  // Non-blocking: folder delete already committed, bin is best-effort
   327→  try {
   328→    await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
   329→    store.setEntries(currentEntries, newSeq);
   330→  } catch {
   331→    console.error('[Bin] addManyToBin publish failed (non-blocking)');
   332→  }
   333→}
   334→
   335→// ---------------------------------------------------------------------------
   336→// Public API: restoreFromBin
   337→// ---------------------------------------------------------------------------
   338→
   339→/**
   340→ * Restore a bin entry to its original folder.
   341→ *
   342→ * Looks up the target folder by IPNS name. If found, re-adds the preserved
   343→ * FolderChild. Handles name collisions (appends " (restored)"). If original
   344→ * parent is also in the bin, attempts recursive parent restore (max depth 5).
   345→ * Falls back to root folder if parent is gone.
   346→ */
   347→export async function restoreFromBin(params: {
   348→  entryId: string;
   349→  userPublicKey: Uint8Array;
   350→  userPrivateKey: Uint8Array;
   351→}): Promise<void> {
   352→  return restoreFromBinInternal(params, 0);
   353→}
   354→
   355→async function restoreFromBinInternal(
   356→  params: { entryId: string; userPublicKey: Uint8Array; userPrivateKey: Uint8Array },
   357→  depth: number
   358→): Promise<void> {
   359→  const { entryId, userPublicKey, userPrivateKey } = params;
   360→
   361→  const binStore = useBinStore.getState();
   362→  const entry = binStore.entries.find((e) => e.id === entryId);
   363→  if (!entry) throw new Error('Bin entry not found');
   364→
   365→  // Resolve original parent folder
   366→  const targetFolder = await resolveTargetFolder(entry.originalParentIpnsName, depth, {
   367→    userPublicKey,
   368→    userPrivateKey,
   369→  });
   370→
   371→  // Get the FolderChild to restore
   372→  const child = getRestoredChild(entry);
   373→
   374→  // Check for name collisions in target folder and rename if needed
   375→  const finalChild = resolveNameCollision(child, targetFolder.children);
   376→
   377→  // Add child back to target folder
   378→  const { updateFolderMetadata } = await import('./folder.service');
   379→  const updatedChildren = [...targetFolder.children, finalChild];
   380→  const { newSequenceNumber } = await updateFolderMetadata({
   381→    folderId: targetFolder.id,
   382→    children: updatedChildren,
   383→    folderKey: targetFolder.folderKey,
   384→    ipnsPrivateKey: targetFolder.ipnsPrivateKey,
   385→    ipnsName: targetFolder.ipnsName,
   386→    sequenceNumber: targetFolder.sequenceNumber,
   387→  });
   388→
   389→  // Update folder store
   390→  const folderStore = useFolderStore.getState();
   391→  folderStore.updateFolderChildren(targetFolder.id, updatedChildren);
   392→  folderStore.updateFolderSequence(targetFolder.id, newSequenceNumber);
   393→
   394→  // If restoring a folder, re-add the folder node to the store
   395→  if (entry.itemType === 'folder' && entry.folderEntry) {
   396→    const existingNode = folderStore.folders[entry.folderEntry.id];
   397→    if (!existingNode) {
   398→      // Create a placeholder node -- it will be fully loaded on next navigation
   399→      folderStore.setFolder({
   400→        id: entry.folderEntry.id,
   401→        name: finalChild.name,
   402→        ipnsName: entry.folderEntry.ipnsName,
   403→        parentId: targetFolder.id,
   404→        children: [],
   405→        isLoaded: false,
   406→        isLoading: false,
   407→        sequenceNumber: 0n,
   408→        // These will be populated when the folder is loaded
   409→        folderKey: new Uint8Array(32),
   410→        ipnsPrivateKey: new Uint8Array(64),
   411→      });
   412→    }
   413→  }
   414→
   415→  // Remove entry from bin metadata and publish
   416→  await removeEntriesFromBin([entryId], { userPublicKey, userPrivateKey });
   417→}
   418→
   419→// ---------------------------------------------------------------------------
   420→// Public API: restoreFromBinBatch
   421→// ---------------------------------------------------------------------------
   422→
   423→/**
   424→ * Restore multiple bin entries, publishing to the bin IPNS only once at the end.
   425→ *
   426→ * Each item is restored to its target folder (which may each require a folder
   427→ * publish), but the bin metadata is updated in a single publish.
   428→ */
   429→export async function restoreFromBinBatch(params: {
   430→  entryIds: string[];
   431→  userPublicKey: Uint8Array;
   432→  userPrivateKey: Uint8Array;
   433→}): Promise<void> {
   434→  const { entryIds, userPublicKey, userPrivateKey } = params;
   435→  if (entryIds.length === 0) return;
   436→
   437→  const { updateFolderMetadata } = await import('./folder.service');
   438→
   439→  const restoredIds: string[] = [];
   440→
   441→  for (const entryId of entryIds) {
   442→    // Read fresh state each iteration — recursive restores may mutate the store
   443→    const entry = useBinStore.getState().entries.find((e) => e.id === entryId);
   444→    if (!entry) continue;
   445→
   446→    try {
   447→      const targetFolder = await resolveTargetFolder(entry.originalParentIpnsName, 0, {
   448→        userPublicKey,
   449→        userPrivateKey,
   450→      });
   451→
   452→      const child = getRestoredChild(entry);
   453→      const finalChild = resolveNameCollision(child, targetFolder.children);
   454→
   455→      const updatedChildren = [...targetFolder.children, finalChild];
   456→      const { newSequenceNumber } = await updateFolderMetadata({
   457→        folderId: targetFolder.id,
   458→        children: updatedChildren,
   459→        folderKey: targetFolder.folderKey,
   460→        ipnsPrivateKey: targetFolder.ipnsPrivateKey,
   461→        ipnsName: targetFolder.ipnsName,
   462→        sequenceNumber: targetFolder.sequenceNumber,
   463→      });
   464→
   465→      const folderStore = useFolderStore.getState();
   466→      folderStore.updateFolderChildren(targetFolder.id, updatedChildren);
   467→      folderStore.updateFolderSequence(targetFolder.id, newSequenceNumber);
   468→
   469→      if (entry.itemType === 'folder' && entry.folderEntry) {
   470→        const existingNode = folderStore.folders[entry.folderEntry.id];
   471→        if (!existingNode) {
   472→          folderStore.setFolder({
   473→            id: entry.folderEntry.id,
   474→            name: finalChild.name,
   475→            ipnsName: entry.folderEntry.ipnsName,
   476→            parentId: targetFolder.id,
   477→            children: [],
   478→            isLoaded: false,
   479→            isLoading: false,
   480→            sequenceNumber: 0n,
   481→            folderKey: new Uint8Array(32),
   482→            ipnsPrivateKey: new Uint8Array(64),
   483→          });
   484→        }
   485→      }
   486→
   487→      restoredIds.push(entryId);
   488→    } catch (err) {
   489→      console.error(`[Bin] Failed to restore entry ${entry.id}:`, err);
   490→    }
   491→  }
   492→
   493→  // Single bin IPNS publish for all restored entries
   494→  if (restoredIds.length > 0) {
   495→    await removeEntriesFromBin(restoredIds, { userPublicKey, userPrivateKey });
   496→  }
   497→}
   498→
   499→// ---------------------------------------------------------------------------
   500→// Public API: permanentlyDelete
   501→// ---------------------------------------------------------------------------
   502→
   503→/**
   504→ * Permanently delete a bin entry: unpin CIDs and update quota.
   505→ *
   506→ * For files: resolves file IPNS -> gets CID -> unpins.
   507→ * For folders: recursively resolves all descendant file CIDs -> unpins all.
   508→ */
   509→export async function permanentlyDelete(params: {
   510→  entryId: string;
   511→  userPublicKey: Uint8Array;
   512→  userPrivateKey: Uint8Array;
   513→}): Promise<void> {
   514→  const { entryId, userPublicKey, userPrivateKey } = params;
   515→
   516→  const binStore = useBinStore.getState();
   517→  const entry = binStore.entries.find((e) => e.id === entryId);
   518→  if (!entry) throw new Error('Bin entry not found');
   519→
   520→  // Perform CID cleanup
   521→  await cleanupEntryCids(entry, userPrivateKey);
   522→
   523→  // Remove from bin metadata and publish
   524→  await removeEntriesFromBin([entryId], { userPublicKey, userPrivateKey });
   525→}
   526→
   527→// ---------------------------------------------------------------------------
   528→// Public API: permanentlyDeleteBatch
   529→// ---------------------------------------------------------------------------
   530→
   531→/**
   532→ * Permanently delete multiple bin entries in a single IPNS publish.
   533→ *
   534→ * Cleans up CIDs for all entries (best-effort), then publishes once.
   535→ */
   536→export async function permanentlyDeleteBatch(params: {
   537→  entryIds: string[];
   538→  userPublicKey: Uint8Array;
   539→  userPrivateKey: Uint8Array;
   540→}): Promise<void> {
   541→  const { entryIds, userPublicKey, userPrivateKey } = params;
   542→  if (entryIds.length === 0) return;
   543→
   544→  const binStore = useBinStore.getState();
   545→  const idsSet = new Set(entryIds);
   546→  const entriesToDelete = binStore.entries.filter((e) => idsSet.has(e.id));
   547→
   548→  // Cleanup CIDs for all entries (best-effort, continue on individual failures)
   549→  for (const entry of entriesToDelete) {
   550→    try {
   551→      await cleanupEntryCids(entry, userPrivateKey);
   552→    } catch (err) {
   553→      console.error(`[Bin] CID cleanup failed for entry ${entry.id}:`, err);
   554→    }
   555→  }
   556→
   557→  // Remove all from bin metadata in a single publish
   558→  await removeEntriesFromBin(entryIds, { userPublicKey, userPrivateKey });
   559→}
   560→
   561→// ---------------------------------------------------------------------------
   562→// Public API: emptyBin
   563→// ---------------------------------------------------------------------------
   564→
   565→/**
   566→ * Permanently delete all bin entries.
   567→ *
   568→ * Processes each entry's CID cleanup, then publishes empty bin metadata.
   569→ */
   570→export async function emptyBin(params: {
   571→  userPublicKey: Uint8Array;
   572→  userPrivateKey: Uint8Array;
   573→}): Promise<void> {
   574→  const { userPublicKey, userPrivateKey } = params;
   575→
   576→  const binStore = useBinStore.getState();
   577→  const entries = [...binStore.entries];
   578→
   579→  // Cleanup CIDs for all entries (best-effort, continue on individual failures)
   580→  for (const entry of entries) {
   581→    try {
   582→      await cleanupEntryCids(entry, userPrivateKey);
   583→    } catch (err) {
   584→      console.error(`[Bin] Failed to cleanup CIDs for entry ${entry.id}:`, err);
   585→    }
   586→  }
   587→
   588→  // Publish empty bin metadata
   589→  const newSeq = binStore.sequenceNumber + 1;
   590→  const metadata: RecycleBinMetadata = {
   591→    version: BIN_METADATA_VERSION,
   592→    sequenceNumber: newSeq,
   593→    entries: [],
   594→  };
   595→
   596→  await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
   597→
   598→  // Update local store
   599→  binStore.setEntries([], newSeq);
   600→}
   601→
   602→// ---------------------------------------------------------------------------
   603→// Public API: purgeExpired
   604→// ---------------------------------------------------------------------------
   605→
   606→/**
   607→ * Purge expired bin entries based on retention period.
   608→ *
   609→ * Filters entries past their retention, cleans up CIDs, and publishes
   610→ * updated bin metadata in a single IPNS publish.
   611→ */
   612→export async function purgeExpired(params: {
   613→  retentionDays: number;
   614→  userPublicKey: Uint8Array;
   615→  userPrivateKey: Uint8Array;
   616→}): Promise<void> {
   617→  const { retentionDays, userPublicKey, userPrivateKey } = params;
   618→
   619→  const binStore = useBinStore.getState();
   620→  const retentionMs = retentionDays * 24 * 60 * 60 * 1000;
