     7→
     8→import { describe, it, expect, beforeEach } from 'vitest';
     9→import { useVaultStore } from '../vault.store';
    10→import { useFolderStore, type FolderNode } from '../folder.store';
    11→
    12→describe('Logout Security', () => {
    13→  beforeEach(() => {
    14→    // Reset stores before each test
