    28→    });
    29→  });
    30→
    31→  describe('useVaultStore.clearVaultKeys', () => {
    32→    it('should zero-fill vault keys on clearVaultKeys', () => {
    33→      // Setup: Create mock keys with known values
    34→      const rootFolderKey = new Uint8Array(32).fill(0xaa);
    35→      const publicKey = new Uint8Array(32).fill(0xbb);
    36→      const privateKey = new Uint8Array(32).fill(0xcc);
    37→
    38→      // Keep references to check after clearing
    39→      const keyReferences = {
    40→        rootFolderKey,
    41→        publicKey,
    42→        privateKey,
    43→      };
    44→
    45→      // Initialize vault with keys
    46→      useVaultStore.getState().setVaultKeys({
    47→        rootFolderKey,
    48→        rootIpnsKeypair: { publicKey, privateKey },
    49→        rootIpnsName: 'k51qzi5uqu5test',
    50→        vaultId: 'test-vault-id',
    51→      });
    52→
    53→      // Verify keys are set
    54→      const stateBefore = useVaultStore.getState();
    55→      expect(stateBefore.rootFolderKey).not.toBeNull();
    56→      expect(stateBefore.rootIpnsKeypair).not.toBeNull();
    57→
    58→      // Clear vault keys
    59→      useVaultStore.getState().clearVaultKeys();
    60→
    61→      // Verify state is cleared
    62→      const stateAfter = useVaultStore.getState();
    63→      expect(stateAfter.rootFolderKey).toBeNull();
    64→      expect(stateAfter.rootIpnsKeypair).toBeNull();
    65→      expect(stateAfter.rootIpnsName).toBeNull();
    66→      expect(stateAfter.vaultId).toBeNull();
    67→      expect(stateAfter.isInitialized).toBe(false);
    68→
    69→      // Verify the original arrays were zero-filled (security check)
    70→      // This confirms memory was overwritten, not just dereferenced
    71→      expect(keyReferences.rootFolderKey.every((b) => b === 0)).toBe(true);
