   250→    await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
   251→    store.setEntries(currentEntries, newSeq);
   252→  } catch {
   253→    console.error('[Bin] addToBin publish failed (non-blocking)');
   254→  }
   255→}
   256→
   257→// ---------------------------------------------------------------------------
   258→// Public API: addManyToBin
   259→// ---------------------------------------------------------------------------
   260→
   261→/**
   262→ * Add multiple deleted items to the recycle bin in a single IPNS publish.
   263→ *
   264→ * Unlike calling addToBin in a loop (which publishes per-item), this batches
   265→ * all entries into one metadata update.
   266→ */
   267→export async function addManyToBin(params: {
