   284→      itemType: isFile ? 'file' : 'folder',
   285→      name: item.name,
   286→      originalParentIpnsName: parentIpnsName,
   287→      originalPath: parentPath,
   288→      deletedAt: now,
   289→      size: 0,
   290→      mimeType: '',
   291→      filePointer: isFile ? (item as FilePointer) : undefined,
   292→      folderEntry: !isFile ? (item as FolderEntry) : undefined,
   293→    };
