   603→// Public API: purgeExpired
   604→// ---------------------------------------------------------------------------
   605→
   606→/**
   607→ * Purge expired bin entries based on retention period.
   608→ *
   609→ * Filters entries past their retention, cleans up CIDs, and publishes
   610→ * updated bin metadata in a single IPNS publish.
   611→ */
   612→export async function purgeExpired(params: {
   613→  retentionDays: number;
   614→  userPublicKey: Uint8Array;
   615→  userPrivateKey: Uint8Array;
   616→}): Promise<void> {
   617→  const { retentionDays, userPublicKey, userPrivateKey } = params;
   618→
   619→  const binStore = useBinStore.getState();
   620→  const retentionMs = retentionDays * 24 * 60 * 60 * 1000;
   621→  const now = Date.now();
   622→
   623→  const expired = binStore.entries.filter((e) => now - e.deletedAt > retentionMs);
   624→  if (expired.length === 0) return;
   625→
   626→  console.log(`[Bin] Purging ${expired.length} expired entries`);
   627→
   628→  // Cleanup CIDs for expired entries (best-effort)
   629→  for (const entry of expired) {
   630→    try {
   631→      await cleanupEntryCids(entry, userPrivateKey);
   632→    } catch (err) {
   633→      console.error(`[Bin] Failed to cleanup CIDs for expired entry ${entry.id}:`, err);
   634→    }
   635→  }
   636→
   637→  // Remove expired entries and publish
   638→  const expiredIds = expired.map((e) => e.id);
   639→  await removeEntriesFromBin(expiredIds, { userPublicKey, userPrivateKey });
   640→}
