   642→// ---------------------------------------------------------------------------
   643→// Internal helpers
   644→// ---------------------------------------------------------------------------
   645→
   646→/**
   647→ * Remove entries from bin metadata and publish the updated metadata.
   648→ */
   649→async function removeEntriesFromBin(
   650→  entryIds: string[],
   651→  params: { userPublicKey: Uint8Array; userPrivateKey: Uint8Array }
   652→): Promise<void> {
   653→  const binStore = useBinStore.getState();
   654→  const idsToRemove = new Set(entryIds);
   655→  const remainingEntries = binStore.entries.filter((e) => !idsToRemove.has(e.id));
   656→  const newSeq = binStore.sequenceNumber + 1;
   657→
   658→  const metadata: RecycleBinMetadata = {
   659→    version: BIN_METADATA_VERSION,
   660→    sequenceNumber: newSeq,
   661→    entries: remainingEntries,
   662→  };
   663→
   664→  await saveBinMetadata({
   665→    metadata,
   666→    userPublicKey: params.userPublicKey,
   667→    userPrivateKey: params.userPrivateKey,
   668→  });
   669→
   670→  // Update local store (use setEntries with explicit seq to avoid double-increment)
   671→  binStore.setEntries(remainingEntries, newSeq);
   672→}
   673→
   674→/**
   675→ * Cleanup CIDs for a bin entry (unpin from IPFS + update quota).
   676→ *
   677→ * Files: use stored contentCid if available, else fall back to IPNS resolution.
   678→ * Folders: unwrap folderKey, decrypt folder metadata, decrypt each nested file's
   679→ * metadata to get CID for unpinning. Recurses for subfolders.
   680→ */
   681→async function cleanupEntryCids(entry: BinEntry, userPrivateKey: Uint8Array): Promise<void> {
   682→  if (entry.itemType === 'file') {
   683→    await unpinFileCids(entry);
   684→  } else if (entry.itemType === 'folder' && entry.folderEntry) {
   685→    await cleanupFolderCids(entry.folderEntry, userPrivateKey);
   686→  }
   687→}
   688→
   689→/**
   690→ * Unpin a single file's content and metadata CIDs, and update quota.
   691→ *
   692→ * Prefers stored contentCid (captured at soft-delete time) to avoid
   693→ * re-decrypting encrypted file metadata (which was the GAP-1 bug).
   694→ * Falls back to legacy IPNS resolution for old entries without contentCid.
   695→ */
   696→async function unpinFileCids(entry: BinEntry): Promise<void> {
   697→  try {
   698→    // Preferred path: use stored contentCid from soft-delete time
   699→    if (entry.contentCid) {
   700→      await unpinFromIpfs(entry.contentCid);
   701→      if (Number.isFinite(entry.contentSize)) {
   702→        useQuotaStore.getState().removeUsage(entry.contentSize!);
   703→      }
   704→      // Also unpin the file metadata CID and any version CIDs
   705→      if (entry.filePointer) {
   706→        const resolved = await resolveIpnsRecord(entry.filePointer.fileMetaIpnsName);
   707→        if (resolved?.cid) {
   708→          // Best-effort: try to parse file metadata for version CIDs.
   709→          // This uses plaintext JSON parsing — if the metadata is encrypted
   710→          // (which it is for v2 entries), version cleanup is skipped here
   711→          // but will succeed for folder-nested files in cleanupFolderCids.
   712→          try {
   713→            const metaBytes = await fetchFromIpfs(resolved.cid);
   714→            const metaJson = new TextDecoder().decode(metaBytes);
   715→            const fileMeta = JSON.parse(metaJson);
   716→            await unpinVersionCids(fileMeta);
   717→          } catch {
   718→            // Expected for encrypted metadata — version cleanup is best-effort
   719→          }
   720→          await unpinFromIpfs(resolved.cid).catch(() => {});
   721→        }
   722→      }
   723→      return;
   724→    }
   725→
   726→    // Fallback for legacy entries without contentCid:
   727→    // Resolve IPNS and attempt to parse file metadata as plaintext JSON.
   728→    // NOTE: This will fail for encrypted file metadata (the original GAP-1 bug).
   729→    // Legacy entries that hit this path will log an error but not crash.
   730→    if (!entry.filePointer) return;
   731→    const fileIpnsName = entry.filePointer.fileMetaIpnsName;
   732→    if (!fileIpnsName) return;
   733→
   734→    const resolved = await resolveIpnsRecord(fileIpnsName);
   735→    if (!resolved?.cid) return;
   736→
   737→    const metaBytes = await fetchFromIpfs(resolved.cid);
   738→    const metaJson = new TextDecoder().decode(metaBytes);
   739→    const fileMeta = JSON.parse(metaJson);
   740→
   741→    if (fileMeta.cid) {
   742→      await unpinFromIpfs(fileMeta.cid);
   743→      if (fileMeta.size && typeof fileMeta.size === 'number') {
   744→        useQuotaStore.getState().removeUsage(fileMeta.size);
   745→      }
   746→    }
   747→    await unpinVersionCids(fileMeta);
   748→
   749→    await unpinFromIpfs(resolved.cid).catch(() => {});
   750→  } catch (err) {
   751→    console.error(`[Bin] CID cleanup failed for file ${entry.id}:`, err);
   752→  }
   753→}
   754→
   755→/**
   756→ * Unpin version CIDs from a decrypted/parsed file metadata object and reclaim quota.
   757→ * Best-effort: errors on individual versions are caught and logged.
   758→ */
   759→async function unpinVersionCids(fileMeta: {
   760→  versions?: Array<{ cid?: string; size?: number }>;
   761→}): Promise<void> {
   762→  if (!Array.isArray(fileMeta.versions)) return;
   763→  for (const version of fileMeta.versions) {
   764→    try {
   765→      if (version.cid) {
   766→        await unpinFromIpfs(version.cid);
   767→      }
   768→      if (Number.isFinite(version.size)) {
   769→        useQuotaStore.getState().removeUsage(version.size!);
   770→      }
   771→    } catch {
   772→      // Best-effort for individual version cleanup
   773→    }
   774→  }
   775→}
   776→
   777→/**
   778→ * Recursively unpin all CIDs in a folder tree.
   779→ *
   780→ * Unwraps the folder's AES key using the user's private key, then decrypts
   781→ * the folder metadata to enumerate children. For each file child, decrypts
   782→ * the file metadata to extract the content CID for unpinning.
   783→ * For subfolder children, recurses with the user's private key.
   784→ */
   785→async function cleanupFolderCids(
   786→  folderEntry: FolderEntry,
   787→  userPrivateKey: Uint8Array
   788→): Promise<void> {
   789→  let folderMetadataCid: string | null = null;
   790→  try {
   791→    // Step 1: Unwrap the folder's AES key using user's private key (ECIES)
   792→    const wrappedFolderKey = hexToBytes(folderEntry.folderKeyEncrypted);
   793→    const folderKey = await unwrapKey(wrappedFolderKey, userPrivateKey);
   794→
   795→    // Step 2: Resolve folder's IPNS to get its metadata CID
   796→    const resolved = await resolveIpnsRecord(folderEntry.ipnsName);
   797→    if (!resolved?.cid) return;
   798→    folderMetadataCid = resolved.cid;
   799→
   800→    // Step 3: Fetch and decrypt the folder metadata
   801→    const metaBytes = await fetchFromIpfs(resolved.cid);
   802→    const metaJson = new TextDecoder().decode(metaBytes);
   803→    const encrypted = JSON.parse(metaJson) as EncryptedFolderMetadata;
   804→    const folderMeta = await decryptFolderMetadata(encrypted, folderKey);
   805→
   806→    // Step 4: For each child, unpin CIDs
   807→    for (const child of folderMeta.children) {
   808→      try {
   809→        if (child.type === 'file') {
   810→          const fp = child as FilePointer;
   811→          // Decrypt file metadata to get content CID
   812→          const fileResolved = await resolveIpnsRecord(fp.fileMetaIpnsName);
   813→          if (fileResolved?.cid) {
   814→            const fileMetaBytes = await fetchFromIpfs(fileResolved.cid);
   815→            const fileMetaJson = new TextDecoder().decode(fileMetaBytes);
   816→            const encryptedFileMeta = JSON.parse(fileMetaJson) as EncryptedFileMetadata;
   817→            const fileMeta = await decryptFileMetadata(encryptedFileMeta, folderKey);
   818→            if (fileMeta.cid) {
   819→              await unpinFromIpfs(fileMeta.cid);
   820→              if (Number.isFinite(fileMeta.size)) {
   821→                useQuotaStore.getState().removeUsage(fileMeta.size);
   822→              }
   823→            }
   824→            // Unpin any historical version CIDs
   825→            await unpinVersionCids(fileMeta);
   826→            // Also unpin the file metadata CID
   827→            await unpinFromIpfs(fileResolved.cid).catch(() => {});
   828→          }
   829→        } else if (child.type === 'folder') {
   830→          // Subfolder: folderKeyEncrypted is ECIES-wrapped with the user's publicKey
   831→          const subFe = child as FolderEntry;
   832→          await cleanupFolderCids(subFe, userPrivateKey);
   833→        }
   834→      } catch (childErr) {
   835→        console.error(`[Bin] Failed to cleanup CIDs for child ${child.name}:`, childErr);
   836→      }
   837→    }
   838→  } catch (err) {
   839→    console.error(`[Bin] Folder CID cleanup failed for ${folderEntry.ipnsName}:`, err);
   840→  } finally {
   841→    // Always unpin the folder metadata CID, even if child cleanup threw
   842→    if (folderMetadataCid) {
   843→      await unpinFromIpfs(folderMetadataCid).catch(() => {});
   844→    }
   845→  }
   846→}
   847→
   848→/**
   849→ * Resolve the target folder for a restore operation.
   850→ *
   851→ * Walks the folder store to find a folder with the given IPNS name.
   852→ * If not found, checks if the parent is in the bin (recursive restore).
   853→ * Falls back to root folder.
   854→ */
   855→async function resolveTargetFolder(
   856→  parentIpnsName: string,
   857→  depth: number,
   858→  params: { userPublicKey: Uint8Array; userPrivateKey: Uint8Array }
   859→): Promise<FolderNode> {
   860→  // Max recursion depth to prevent infinite loops
   861→  if (depth > 5) {
   862→    console.warn('[Bin] Max restore depth reached, falling back to root');
   863→    return getRootFolder();
   864→  }
   865→
   866→  // Look up folder by IPNS name in folder store
   867→  const folders = useFolderStore.getState().folders;
   868→  const targetFolder = Object.values(folders).find((f) => f.ipnsName === parentIpnsName);
   869→
   870→  if (targetFolder) {
   871→    return targetFolder;
   872→  }
   873→
   874→  // Check if parent is in the bin
   875→  const binStore = useBinStore.getState();
   876→  const parentBinEntry = binStore.entries.find(
   877→    (e) => e.itemType === 'folder' && e.folderEntry && e.folderEntry.ipnsName === parentIpnsName
   878→  );
   879→
   880→  if (parentBinEntry) {
   881→    // Restore parent first (recursive, depth incremented)
   882→    console.log(`[Bin] Restoring parent folder (id: ${parentBinEntry.id}) first`);
   883→    await restoreFromBinInternal(
   884→      {
   885→        entryId: parentBinEntry.id,
   886→        userPublicKey: params.userPublicKey,
   887→        userPrivateKey: params.userPrivateKey,
   888→      },
   889→      depth + 1
   890→    );
   891→
   892→    // After restoring parent, try to find it again
   893→    const updatedFolders = useFolderStore.getState().folders;
   894→    const restoredParent = Object.values(updatedFolders).find((f) => f.ipnsName === parentIpnsName);
   895→    if (restoredParent) {
   896→      return restoredParent;
   897→    }
   898→  }
   899→
   900→  // Parent truly gone -- restore to root
   901→  console.warn(`[Bin] Original parent not found (${parentIpnsName}), restoring to root`);
   902→  return getRootFolder();
   903→}
   904→
   905→/**
   906→ * Get the root folder from the folder store.
   907→ */
   908→function getRootFolder(): FolderNode {
   909→  const folders = useFolderStore.getState().folders;
   910→  const root = folders['root'];
   911→  if (root) return root;
   912→
   913→  // Fallback: construct from vault store
   914→  const vault = useVaultStore.getState();
   915→  if (!vault.rootFolderKey || !vault.rootIpnsKeypair || !vault.rootIpnsName) {
