    60→
    61→      // Verify state is cleared
    62→      const stateAfter = useVaultStore.getState();
    63→      expect(stateAfter.rootFolderKey).toBeNull();
    64→      expect(stateAfter.rootIpnsKeypair).toBeNull();
    65→      expect(stateAfter.rootIpnsName).toBeNull();
    66→      expect(stateAfter.vaultId).toBeNull();
    67→      expect(stateAfter.isInitialized).toBe(false);
    68→
    69→      // Verify the original arrays were zero-filled (security check)
