    16→ */
    17→function simulateErrorRecovery(
    18→  errorMessage: string,
    19→  uploadedFiles: { cid: string }[] | undefined,
    20→  unpinFn: (cid: string) => Promise<void>,
    21→  fetchQuotaFn: () => Promise<void>
