   335→// ---------------------------------------------------------------------------
   336→// Public API: restoreFromBin
   337→// ---------------------------------------------------------------------------
   338→
   339→/**
   340→ * Restore a bin entry to its original folder.
   341→ *
   342→ * Looks up the target folder by IPNS name. If found, re-adds the preserved
   343→ * FolderChild. Handles name collisions (appends " (restored)"). If original
   344→ * parent is also in the bin, attempts recursive parent restore (max depth 5).
   345→ * Falls back to root folder if parent is gone.
   346→ */
   347→export async function restoreFromBin(params: {
   348→  entryId: string;
   349→  userPublicKey: Uint8Array;
   350→  userPrivateKey: Uint8Array;
   351→}): Promise<void> {
   352→  return restoreFromBinInternal(params, 0);
   353→}
   354→
   355→async function restoreFromBinInternal(
   356→  params: { entryId: string; userPublicKey: Uint8Array; userPrivateKey: Uint8Array },
   357→  depth: number
   358→): Promise<void> {
   359→  const { entryId, userPublicKey, userPrivateKey } = params;
   360→
   361→  const binStore = useBinStore.getState();
   362→  const entry = binStore.entries.find((e) => e.id === entryId);
   363→  if (!entry) throw new Error('Bin entry not found');
   364→
   365→  // Resolve original parent folder
   366→  const targetFolder = await resolveTargetFolder(entry.originalParentIpnsName, depth, {
   367→    userPublicKey,
   368→    userPrivateKey,
   369→  });
   370→
   371→  // Get the FolderChild to restore
   372→  const child = getRestoredChild(entry);
   373→
   374→  // Check for name collisions in target folder and rename if needed
   375→  const finalChild = resolveNameCollision(child, targetFolder.children);
   376→
   377→  // Add child back to target folder
   378→  const { updateFolderMetadata } = await import('./folder.service');
   379→  const updatedChildren = [...targetFolder.children, finalChild];
   380→  const { newSequenceNumber } = await updateFolderMetadata({
   381→    folderId: targetFolder.id,
   382→    children: updatedChildren,
   383→    folderKey: targetFolder.folderKey,
   384→    ipnsPrivateKey: targetFolder.ipnsPrivateKey,
   385→    ipnsName: targetFolder.ipnsName,
   386→    sequenceNumber: targetFolder.sequenceNumber,
   387→  });
   388→
   389→  // Update folder store
   390→  const folderStore = useFolderStore.getState();
   391→  folderStore.updateFolderChildren(targetFolder.id, updatedChildren);
   392→  folderStore.updateFolderSequence(targetFolder.id, newSequenceNumber);
   393→
   394→  // If restoring a folder, re-add the folder node to the store
   395→  if (entry.itemType === 'folder' && entry.folderEntry) {
   396→    const existingNode = folderStore.folders[entry.folderEntry.id];
   397→    if (!existingNode) {
   398→      // Create a placeholder node -- it will be fully loaded on next navigation
   399→      folderStore.setFolder({
   400→        id: entry.folderEntry.id,
   401→        name: finalChild.name,
   402→        ipnsName: entry.folderEntry.ipnsName,
   403→        parentId: targetFolder.id,
   404→        children: [],
   405→        isLoaded: false,
   406→        isLoading: false,
   407→        sequenceNumber: 0n,
   408→        // These will be populated when the folder is loaded
   409→        folderKey: new Uint8Array(32),
   410→        ipnsPrivateKey: new Uint8Array(64),
   411→      });
   412→    }
   413→  }
   414→
   415→  // Remove entry from bin metadata and publish
   416→  await removeEntriesFromBin([entryId], { userPublicKey, userPrivateKey });
   417→}
   418→
   419→// ---------------------------------------------------------------------------
   420→// Public API: restoreFromBinBatch
   421→// ---------------------------------------------------------------------------
   422→
   423→/**
   424→ * Restore multiple bin entries, publishing to the bin IPNS only once at the end.
   425→ *
   426→ * Each item is restored to its target folder (which may each require a folder
   427→ * publish), but the bin metadata is updated in a single publish.
   428→ */
   429→export async function restoreFromBinBatch(params: {
   430→  entryIds: string[];
   431→  userPublicKey: Uint8Array;
   432→  userPrivateKey: Uint8Array;
   433→}): Promise<void> {
   434→  const { entryIds, userPublicKey, userPrivateKey } = params;
   435→  if (entryIds.length === 0) return;
   436→
   437→  const { updateFolderMetadata } = await import('./folder.service');
   438→
   439→  const restoredIds: string[] = [];
   440→
   441→  for (const entryId of entryIds) {
   442→    // Read fresh state each iteration — recursive restores may mutate the store
   443→    const entry = useBinStore.getState().entries.find((e) => e.id === entryId);
   444→    if (!entry) continue;
   445→
   446→    try {
   447→      const targetFolder = await resolveTargetFolder(entry.originalParentIpnsName, 0, {
   448→        userPublicKey,
   449→        userPrivateKey,
   450→      });
   451→
   452→      const child = getRestoredChild(entry);
   453→      const finalChild = resolveNameCollision(child, targetFolder.children);
   454→
   455→      const updatedChildren = [...targetFolder.children, finalChild];
   456→      const { newSequenceNumber } = await updateFolderMetadata({
   457→        folderId: targetFolder.id,
   458→        children: updatedChildren,
   459→        folderKey: targetFolder.folderKey,
   460→        ipnsPrivateKey: targetFolder.ipnsPrivateKey,
   461→        ipnsName: targetFolder.ipnsName,
   462→        sequenceNumber: targetFolder.sequenceNumber,
   463→      });
   464→
   465→      const folderStore = useFolderStore.getState();
   466→      folderStore.updateFolderChildren(targetFolder.id, updatedChildren);
   467→      folderStore.updateFolderSequence(targetFolder.id, newSequenceNumber);
   468→
   469→      if (entry.itemType === 'folder' && entry.folderEntry) {
   470→        const existingNode = folderStore.folders[entry.folderEntry.id];
   471→        if (!existingNode) {
   472→          folderStore.setFolder({
   473→            id: entry.folderEntry.id,
   474→            name: finalChild.name,
   475→            ipnsName: entry.folderEntry.ipnsName,
   476→            parentId: targetFolder.id,
   477→            children: [],
   478→            isLoaded: false,
   479→            isLoading: false,
   480→            sequenceNumber: 0n,
   481→            folderKey: new Uint8Array(32),
   482→            ipnsPrivateKey: new Uint8Array(64),
   483→          });
   484→        }
   485→      }
   486→
   487→      restoredIds.push(entryId);
   488→    } catch (err) {
   489→      console.error(`[Bin] Failed to restore entry ${entry.id}:`, err);
   490→    }
   491→  }
   492→
   493→  // Single bin IPNS publish for all restored entries
   494→  if (restoredIds.length > 0) {
   495→    await removeEntriesFromBin(restoredIds, { userPublicKey, userPrivateKey });
   496→  }
   497→}
