   499→// ---------------------------------------------------------------------------
   500→// Public API: permanentlyDelete
   501→// ---------------------------------------------------------------------------
   502→
   503→/**
   504→ * Permanently delete a bin entry: unpin CIDs and update quota.
   505→ *
   506→ * For files: resolves file IPNS -> gets CID -> unpins.
   507→ * For folders: recursively resolves all descendant file CIDs -> unpins all.
   508→ */
   509→export async function permanentlyDelete(params: {
   510→  entryId: string;
   511→  userPublicKey: Uint8Array;
   512→  userPrivateKey: Uint8Array;
   513→}): Promise<void> {
   514→  const { entryId, userPublicKey, userPrivateKey } = params;
   515→
   516→  const binStore = useBinStore.getState();
   517→  const entry = binStore.entries.find((e) => e.id === entryId);
   518→  if (!entry) throw new Error('Bin entry not found');
   519→
   520→  // Perform CID cleanup
   521→  await cleanupEntryCids(entry, userPrivateKey);
   522→
   523→  // Remove from bin metadata and publish
   524→  await removeEntriesFromBin([entryId], { userPublicKey, userPrivateKey });
   525→}
