   527→// ---------------------------------------------------------------------------
   528→// Public API: permanentlyDeleteBatch
   529→// ---------------------------------------------------------------------------
   530→
   531→/**
   532→ * Permanently delete multiple bin entries in a single IPNS publish.
   533→ *
   534→ * Cleans up CIDs for all entries (best-effort), then publishes once.
   535→ */
   536→export async function permanentlyDeleteBatch(params: {
   537→  entryIds: string[];
   538→  userPublicKey: Uint8Array;
   539→  userPrivateKey: Uint8Array;
   540→}): Promise<void> {
   541→  const { entryIds, userPublicKey, userPrivateKey } = params;
   542→  if (entryIds.length === 0) return;
   543→
   544→  const binStore = useBinStore.getState();
   545→  const idsSet = new Set(entryIds);
   546→  const entriesToDelete = binStore.entries.filter((e) => idsSet.has(e.id));
   547→
   548→  // Cleanup CIDs for all entries (best-effort, continue on individual failures)
   549→  for (const entry of entriesToDelete) {
   550→    try {
   551→      await cleanupEntryCids(entry, userPrivateKey);
   552→    } catch (err) {
   553→      console.error(`[Bin] CID cleanup failed for entry ${entry.id}:`, err);
   554→    }
   555→  }
   556→
   557→  // Remove all from bin metadata in a single publish
   558→  await removeEntriesFromBin(entryIds, { userPublicKey, userPrivateKey });
   559→}
