   561→// ---------------------------------------------------------------------------
   562→// Public API: emptyBin
   563→// ---------------------------------------------------------------------------
   564→
   565→/**
   566→ * Permanently delete all bin entries.
   567→ *
   568→ * Processes each entry's CID cleanup, then publishes empty bin metadata.
   569→ */
   570→export async function emptyBin(params: {
   571→  userPublicKey: Uint8Array;
   572→  userPrivateKey: Uint8Array;
   573→}): Promise<void> {
   574→  const { userPublicKey, userPrivateKey } = params;
   575→
   576→  const binStore = useBinStore.getState();
   577→  const entries = [...binStore.entries];
   578→
   579→  // Cleanup CIDs for all entries (best-effort, continue on individual failures)
   580→  for (const entry of entries) {
   581→    try {
   582→      await cleanupEntryCids(entry, userPrivateKey);
   583→    } catch (err) {
   584→      console.error(`[Bin] Failed to cleanup CIDs for entry ${entry.id}:`, err);
   585→    }
   586→  }
   587→
   588→  // Publish empty bin metadata
   589→  const newSeq = binStore.sequenceNumber + 1;
   590→  const metadata: RecycleBinMetadata = {
   591→    version: BIN_METADATA_VERSION,
   592→    sequenceNumber: newSeq,
   593→    entries: [],
   594→  };
   595→
   596→  await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
   597→
   598→  // Update local store
