   777→/**
   778→ * Recursively unpin all CIDs in a folder tree.
   779→ *
   780→ * Unwraps the folder's AES key using the user's private key, then decrypts
   781→ * the folder metadata to enumerate children. For each file child, decrypts
   782→ * the file metadata to extract the content CID for unpinning.
   783→ * For subfolder children, recurses with the user's private key.
   784→ */
   785→async function cleanupFolderCids(
   786→  folderEntry: FolderEntry,
   787→  userPrivateKey: Uint8Array
   788→): Promise<void> {
   789→  let folderMetadataCid: string | null = null;
   790→  try {
   791→    // Step 1: Unwrap the folder's AES key using user's private key (ECIES)
   792→    const wrappedFolderKey = hexToBytes(folderEntry.folderKeyEncrypted);
   793→    const folderKey = await unwrapKey(wrappedFolderKey, userPrivateKey);
   794→
   795→    // Step 2: Resolve folder's IPNS to get its metadata CID
   796→    const resolved = await resolveIpnsRecord(folderEntry.ipnsName);
   797→    if (!resolved?.cid) return;
   798→    folderMetadataCid = resolved.cid;
   799→
   800→    // Step 3: Fetch and decrypt the folder metadata
   801→    const metaBytes = await fetchFromIpfs(resolved.cid);
   802→    const metaJson = new TextDecoder().decode(metaBytes);
   803→    const encrypted = JSON.parse(metaJson) as EncryptedFolderMetadata;
   804→    const folderMeta = await decryptFolderMetadata(encrypted, folderKey);
   805→
   806→    // Step 4: For each child, unpin CIDs
   807→    for (const child of folderMeta.children) {
   808→      try {
   809→        if (child.type === 'file') {
   810→          const fp = child as FilePointer;
   811→          // Decrypt file metadata to get content CID
   812→          const fileResolved = await resolveIpnsRecord(fp.fileMetaIpnsName);
   813→          if (fileResolved?.cid) {
   814→            const fileMetaBytes = await fetchFromIpfs(fileResolved.cid);
   815→            const fileMetaJson = new TextDecoder().decode(fileMetaBytes);
   816→            const encryptedFileMeta = JSON.parse(fileMetaJson) as EncryptedFileMetadata;
   817→            const fileMeta = await decryptFileMetadata(encryptedFileMeta, folderKey);
   818→            if (fileMeta.cid) {
   819→              await unpinFromIpfs(fileMeta.cid);
   820→              if (Number.isFinite(fileMeta.size)) {
   821→                useQuotaStore.getState().removeUsage(fileMeta.size);
   822→              }
   823→            }
   824→            // Unpin any historical version CIDs
   825→            await unpinVersionCids(fileMeta);
   826→            // Also unpin the file metadata CID
   827→            await unpinFromIpfs(fileResolved.cid).catch(() => {});
   828→          }
   829→        } else if (child.type === 'folder') {
   830→          // Subfolder: folderKeyEncrypted is ECIES-wrapped with the user's publicKey
   831→          const subFe = child as FolderEntry;
   832→          await cleanupFolderCids(subFe, userPrivateKey);
   833→        }
   834→      } catch (childErr) {
   835→        console.error(`[Bin] Failed to cleanup CIDs for child ${child.name}:`, childErr);
   836→      }
   837→    }
   838→  } catch (err) {
   839→    console.error(`[Bin] Folder CID cleanup failed for ${folderEntry.ipnsName}:`, err);
   840→  } finally {
   841→    // Always unpin the folder metadata CID, even if child cleanup threw
   842→    if (folderMetadataCid) {
   843→      await unpinFromIpfs(folderMetadataCid).catch(() => {});
   844→    }
   845→  }
   846→}
