  1→import { useEffect, useRef, useState } from 'react';
  2→import { Portal } from '../ui/Portal';
  3→import { UploadItem } from './UploadItem';
  4→import { useUploadStore } from '../../stores/upload.store';
  5→import '../../styles/upload.css';
  6→
  7→/**
  8→ * Map upload store status to display status.
  9→ */
 10→function mapStatus(
 11→  storeStatus: ReturnType<typeof useUploadStore.getState>['status']
 12→): 'pending' | 'encrypting' | 'uploading' | 'complete' | 'error' {
 13→  switch (storeStatus) {
 14→    case 'encrypting':
 15→      return 'encrypting';
 16→    case 'uploading':
 17→      return 'uploading';
 18→    case 'success':
 19→      return 'complete';
 20→    case 'error':
 21→    case 'cancelled':
 22→      return 'error';
 23→    default:
 24→      return 'pending';
 25→  }
 26→}
 27→
 28→/**
 29→ * Get header title based on upload status.
 30→ */
 31→function getTitle(
 32→  status: ReturnType<typeof useUploadStore.getState>['status'],
 33→  completedFiles: number,
 34→  totalFiles: number
 35→): string {
 36→  switch (status) {
 37→    case 'success':
 38→      return 'Upload Complete';
 39→    case 'error':
 40→      return 'Upload Failed';
 41→    case 'cancelled':
 42→      return 'Upload Cancelled';
 43→    case 'registering':
 44→      return 'Registering Files...';
 45→    default:
 46→      return `Uploading (${completedFiles}/${totalFiles})`;
 47→  }
 48→}
 49→
 50→/**
 51→ * Collapsible upload popup widget – bottom-right corner.
 52→ *
 53→ * Always rendered in the DOM (via Portal) but visually hidden when idle.
 54→ * Expands automatically when an upload starts, collapses on success after a
 55→ * short delay.  The user can manually toggle expanded/collapsed at any time
 56→ * via the header chevron.
 57→ */
 58→export function UploadModal() {
 59→  const status = useUploadStore((state) => state.status);
 60→  const progress = useUploadStore((state) => state.progress);
 61→  const currentFile = useUploadStore((state) => state.currentFile);
 62→  const totalFiles = useUploadStore((state) => state.totalFiles);
 63→  const completedFiles = useUploadStore((state) => state.completedFiles);
 64→  const error = useUploadStore((state) => state.error);
 65→  const cancel = useUploadStore((state) => state.cancel);
 66→  const reset = useUploadStore((state) => state.reset);
 67→
 68→  const [expanded, setExpanded] = useState(false);
 69→  const [visible, setVisible] = useState(false);
 70→
 71→  const prevStatusRef = useRef(status);
 72→  const autoCollapseTimer = useRef<ReturnType<typeof setTimeout>>();
 73→  const autoHideTimer = useRef<ReturnType<typeof setTimeout>>();
 74→
 75→  const isActive = status !== 'idle';
 76→  const canCancel = status === 'encrypting' || status === 'uploading';
 77→  const canClose = status === 'success' || status === 'error' || status === 'cancelled';
 78→
 79→  // --- visibility & expand/collapse automation ---
 80→  useEffect(() => {
 81→    const prev = prevStatusRef.current;
 82→    prevStatusRef.current = status;
 83→
 84→    // Clear pending timers on every status change
 85→    clearTimeout(autoCollapseTimer.current);
 86→    clearTimeout(autoHideTimer.current);
 87→
 88→    if (status !== 'idle' && prev === 'idle') {
 89→      // Upload just started → show & expand
 90→      setVisible(true);
 91→      setExpanded(true);
 92→    }
 93→
 94→    if (status === 'success') {
 95→      // Auto-collapse after 1.5s, then hide after the collapse animation (300ms)
 96→      autoCollapseTimer.current = setTimeout(() => {
 97→        setExpanded(false);
 98→        autoHideTimer.current = setTimeout(() => {
 99→          reset();
100→          setVisible(false);
101→        }, 400);
102→      }, 1500);
103→    }
104→
105→    return () => {
106→      clearTimeout(autoCollapseTimer.current);
107→      clearTimeout(autoHideTimer.current);
108→    };
109→  }, [status, reset]);
110→
111→  // Keep visible flag in sync when store resets externally
112→  useEffect(() => {
113→    if (!isActive && !expanded) {
114→      // Small delay so the collapse animation can finish before we unmount
115→      const t = setTimeout(() => setVisible(false), 400);
116→      return () => clearTimeout(t);
117→    }
118→    if (isActive) {
119→      setVisible(true);
120→    }
121→    return undefined;
122→  }, [isActive, expanded]);
123→
124→  const handleToggle = () => setExpanded((e) => !e);
125→
126→  const handleClose = () => {
127→    clearTimeout(autoCollapseTimer.current);
128→    clearTimeout(autoHideTimer.current);
129→    setExpanded(false);
130→    setTimeout(() => {
131→      reset();
132→      setVisible(false);
133→    }, 400);
134→  };
135→
136→  const handleCancel = () => cancel();
137→
138→  const title = getTitle(status, completedFiles, totalFiles);
139→  const itemStatus = mapStatus(status);
140→
141→  if (!visible) return null;
142→
143→  return (
144→    <Portal>
145→      <div
146→        className={`upload-popup ${expanded ? 'upload-popup--expanded' : 'upload-popup--collapsed'}`}
147→        role="region"
148→        aria-label="Upload progress"
149→      >
150→        {/* Header – always visible, acts as toggle */}
151→        <button
152→          type="button"
153→          className="upload-popup-header"
154→          onClick={handleToggle}
155→          aria-expanded={expanded}
156→        >
157→          <span className="upload-popup-header-left">
158→            <span className="upload-popup-icon" aria-hidden="true">
159→              {status === 'success' ? '\u2713' : status === 'error' ? '!' : '\u2191'}
160→            </span>
161→            <span className="upload-popup-title">{isActive ? title : 'Uploads'}</span>
162→          </span>
163→
164→          {/* Mini progress indicator visible when collapsed & active */}
165→          {!expanded && isActive && status !== 'success' && status !== 'error' && (
166→            <span className="upload-popup-mini-progress">{progress}%</span>
167→          )}
168→
169→          <span
170→            className={`upload-popup-chevron ${expanded ? 'upload-popup-chevron--down' : ''}`}
171→            aria-hidden="true"
172→          >
173→            {'\u25B2'}
174→          </span>
175→        </button>
176→
177→        {/* Body – shown when expanded */}
178→        <div className="upload-popup-body">
179→          <div className="upload-popup-progress-bar">
180→            <div
181→              className="upload-popup-progress-fill"
182→              style={{ width: `${progress}%` }}
183→              data-status={itemStatus}
184→            />
185→          </div>
186→
187→          <div className="upload-popup-overall">
188→            <span>
189→              {completedFiles} of {totalFiles} files
190→            </span>
191→            <span>{progress}%</span>
192→          </div>
193→
194→          {/* Current file being processed */}
195→          <div className="upload-popup-items">
196→            {currentFile && (
197→              <UploadItem
198→                filename={currentFile}
199→                status={itemStatus}
200→                progress={itemStatus === 'complete' ? 100 : progress}
201→                error={error}
202→                onCancel={canCancel ? handleCancel : undefined}
203→              />
204→            )}
205→
206→            {status === 'registering' && !currentFile && (
207→              <div className="upload-item-status">Updating folder metadata...</div>
208→            )}
209→
210→            {status === 'error' && error && !currentFile && (
211→              <div className="upload-zone-error" role="alert">
212→                {error}
213→              </div>
214→            )}
215→          </div>
216→
217→          {/* Action buttons */}
218→          <div className="upload-popup-actions">
219→            {canCancel && (
220→              <button
221→                type="button"
222→                className="upload-modal-btn upload-modal-btn-cancel"
223→                onClick={handleCancel}
224→              >
225→                Cancel
226→              </button>
227→            )}
228→            {canClose && (
229→              <button
230→                type="button"
231→                className="upload-modal-btn upload-modal-btn-close"
232→                onClick={handleClose}
233→              >
234→                Close
235→              </button>
236→            )}
237→          </div>
238→        </div>
239→      </div>
240→    </Portal>
241→  );
242→}
