 1→import { useCallback } from 'react';
 2→import { uploadFiles, UploadedFile } from '../services/upload.service';
 3→import { useUploadStore } from '../stores/upload.store';
 4→import { useQuotaStore } from '../stores/quota.store';
 5→import { useAuthStore } from '../stores/auth.store';
 6→
 7→/**
 8→ * React hook for file upload with encryption, progress tracking, and quota management.
 9→ *
10→ * @example
11→ * ```tsx
12→ * function UploadButton() {
13→ *   const {
14→ *     upload,
15→ *     cancel,
16→ *     reset,
17→ *     isUploading,
18→ *     progress,
19→ *     currentFile,
20→ *     error,
21→ *     canUpload,
22→ *   } = useFileUpload();
23→ *
24→ *   const handleFiles = async (files: File[]) => {
25→ *     const totalSize = files.reduce((s, f) => s + f.size, 0);
26→ *     if (!canUpload(totalSize)) {
27→ *       alert('Not enough space');
28→ *       return;
29→ *     }
30→ *     try {
31→ *       const results = await upload(files);
32→ *       console.log('Uploaded:', results);
33→ *     } catch (err) {
34→ *       // Error already in state via error
35→ *     }
36→ *   };
37→ *
38→ *   return (
39→ *     <div>
40→ *       {isUploading && <div>Uploading {currentFile}... {progress}%</div>}
41→ *       {error && <div>Error: {error}</div>}
42→ *       <button onClick={() => cancel()} disabled={!isUploading}>Cancel</button>
43→ *     </div>
44→ *   );
45→ * }
46→ * ```
47→ */
48→export function useFileUpload() {
49→  const { status, progress, currentFile, totalFiles, completedFiles, error, cancel, reset } =
50→    useUploadStore();
51→
52→  const { usedBytes, limitBytes, remainingBytes, canUpload, fetchQuota } = useQuotaStore();
53→  const { vaultKeypair } = useAuthStore();
54→
55→  const upload = useCallback(
56→    async (files: File[]): Promise<UploadedFile[]> => {
57→      if (!vaultKeypair) {
58→        throw new Error('No keypair available - please log in again');
59→      }
60→
61→      // Refresh quota before upload
62→      await fetchQuota();
63→
64→      return uploadFiles(files, vaultKeypair.publicKey);
65→    },
66→    [vaultKeypair, fetchQuota]
67→  );
68→
69→  return {
70→    // State
71→    status,
72→    progress,
73→    currentFile,
74→    totalFiles,
75→    completedFiles,
76→    error,
77→    isUploading: status === 'encrypting' || status === 'uploading' || status === 'registering',
78→
79→    // Quota
80→    usedBytes,
81→    limitBytes,
82→    remainingBytes,
83→    canUpload,
84→
85→    // Actions
86→    upload,
87→    cancel,
88→    reset,
89→  };
90→}
