 1→import { create } from 'zustand';
 2→import axios from 'axios';
 3→
 4→type UploadStatus =
 5→  | 'idle'
 6→  | 'encrypting'
 7→  | 'uploading'
 8→  | 'registering'
 9→  | 'success'
10→  | 'error'
11→  | 'cancelled';
12→
13→type UploadState = {
14→  status: UploadStatus;
15→  progress: number; // 0-100 for current batch
16→  currentFile: string | null;
17→  totalFiles: number;
18→  completedFiles: number;
19→  error: string | null;
20→  cancelSource: ReturnType<typeof axios.CancelToken.source> | null;
21→
22→  startUpload: (totalFiles: number) => void;
23→  setEncrypting: (filename: string) => void;
24→  setUploading: (filename: string, progress: number) => void;
25→  fileComplete: () => void;
26→  setRegistering: () => void;
27→  setSuccess: () => void;
28→  setError: (error: string) => void;
29→  cancel: () => void;
30→  reset: () => void;
31→};
32→
33→export const useUploadStore = create<UploadState>((set, get) => ({
34→  status: 'idle',
35→  progress: 0,
36→  currentFile: null,
37→  totalFiles: 0,
38→  completedFiles: 0,
39→  error: null,
40→  cancelSource: null,
41→
42→  startUpload: (totalFiles) =>
43→    set({
44→      status: 'encrypting',
45→      progress: 0,
46→      totalFiles,
47→      completedFiles: 0,
48→      error: null,
49→      cancelSource: axios.CancelToken.source(),
50→    }),
51→
52→  setEncrypting: (filename) => set({ status: 'encrypting', currentFile: filename }),
53→
54→  setUploading: (filename, progress) => {
55→    const { completedFiles, totalFiles } = get();
56→    const baseProgress = (completedFiles / totalFiles) * 100;
57→    const fileProgress = progress / totalFiles;
58→    set({
59→      status: 'uploading',
60→      currentFile: filename,
61→      progress: Math.round(baseProgress + fileProgress),
62→    });
63→  },
64→
65→  fileComplete: () =>
66→    set((state) => ({
67→      completedFiles: state.completedFiles + 1,
68→      progress: Math.round(((state.completedFiles + 1) / state.totalFiles) * 100),
69→    })),
70→
71→  setRegistering: () => set({ status: 'registering', currentFile: null }),
72→  setSuccess: () => set({ status: 'success', progress: 100, currentFile: null }),
73→  setError: (error) => set({ status: 'error', error, currentFile: null }),
74→
75→  cancel: () => {
76→    const { cancelSource } = get();
77→    if (cancelSource) {
78→      cancelSource.cancel('Upload cancelled by user');
79→    }
80→    set({ status: 'cancelled', currentFile: null });
81→  },
82→
83→  reset: () =>
84→    set({
85→      status: 'idle',
86→      progress: 0,
87→      currentFile: null,
88→      totalFiles: 0,
89→      completedFiles: 0,
90→      error: null,
91→      cancelSource: null,
92→    }),
93→}));
94→

596→export async function addFilesToFolder(params: {
597→  parentFolderState: FolderNode;
598→  files: Array<{
599→    fileId: string;
600→    name: string;
601→    fileIpnsRecord: FileIpnsRecordPayload;
602→    ipnsPrivateKeyEncrypted: string;
603→  }>;
604→}): Promise<{ filePointers: FilePointer[]; newSequenceNumber: bigint }> {
605→  // 1. Build a set of existing child names for collision detection
606→  const existingNames = new Set(params.parentFolderState.children.map((c) => c.name));
607→
608→  // 2. Create FilePointer for each file, checking collisions
609→  const filePointers: FilePointer[] = [];
610→  const now = Date.now();
611→
612→  for (const file of params.files) {
613→    if (existingNames.has(file.name)) {
614→      throw new Error(`A file with name "${file.name}" already exists`);
615→    }
616→    existingNames.add(file.name);
617→
618→    const filePointer: FilePointer = {
619→      type: 'file',
620→      id: file.fileId,
621→      name: file.name,
622→      fileMetaIpnsName: file.fileIpnsRecord.ipnsName,
623→      ipnsPrivateKeyEncrypted: file.ipnsPrivateKeyEncrypted,
624→      createdAt: now,
625→      modifiedAt: now,
626→    };
627→    filePointers.push(filePointer);
628→  }
629→
630→  // 3. Build updated children array
631→  const children: FolderChild[] = [...params.parentFolderState.children, ...filePointers];
632→
633→  // 4. Build folder IPNS record
634→  const folderResult = await buildFolderIpnsRecord({
635→    children,
636→    folderKey: params.parentFolderState.folderKey,
637→    ipnsPrivateKey: params.parentFolderState.ipnsPrivateKey,
638→    ipnsName: params.parentFolderState.ipnsName,
639→    sequenceNumber: params.parentFolderState.sequenceNumber,
640→  });
641→
642→  // 5. Batch publish: all N file IPNS records + 1 folder IPNS record (single API call)
643→  const allRecords = [
644→    ...params.files.map((f) => ({ ...f.fileIpnsRecord, recordType: 'file' as const })),
645→    folderResult.record,
646→  ];
647→  const publishResult = await batchPublishIpnsRecords(allRecords);
648→
649→  if (publishResult.totalFailed > 0) {
650→    console.error(
651→      `Batch publish partial failure: ${publishResult.totalFailed}/${publishResult.totalFailed + publishResult.totalSucceeded} records failed`
652→    );
653→    throw new Error('Failed to publish one or more IPNS records');
654→  }
655→
656→  return { filePointers, newSequenceNumber: folderResult.newSequenceNumber };
657→}
658→
659→/**
660→ * Replace file content in v2 metadata (content update).
661→ *
662→ * THIS IS THE PRIMARY BENEFIT OF PER-FILE IPNS: content updates publish
663→ * ONLY the file's IPNS record. The folder metadata is NOT touched because
664→ * the FilePointer still points to the same fileMetaIpnsName, which now
665→ * resolves to the updated content.
666→ *
667→ * @param params.fileId - ID of file to update
668→ * @param params.fileIpnsRecord - Updated file IPNS record from updateFileMetadata
669→ * @param params.parentFolderState - Parent folder (used only to find the FilePointer)
670→ * @returns Void -- no folder metadata update needed
671→ * @throws Error if file not found
672→ */
673→export async function replaceFileInFolder(params: {
674→  fileId: string;
675→  fileIpnsRecord: FileIpnsRecordPayload;
676→  parentFolderState: FolderNode;
677→}): Promise<void> {
678→  // 1. Verify file exists in parent's children
679→  const fileExists = params.parentFolderState.children.some(
680→    (c) => c.type === 'file' && c.id === params.fileId
681→  );
682→
683→  if (!fileExists) throw new Error('File not found');
684→
685→  // 2. Publish ONLY the file IPNS record (folder metadata untouched!)
686→  // This is the key optimization: content update does NOT modify folder metadata.
687→  const publishResult = await batchPublishIpnsRecords([
688→    { ...params.fileIpnsRecord, recordType: 'file' },
689→  ]);
690→
691→  if (publishResult.totalFailed > 0) {
692→    throw new Error('Failed to publish file IPNS record');
693→  }
694→}
