  1→import { useState, useEffect, useCallback, useMemo, type KeyboardEvent } from 'react';
  2→import type { FolderChild } from '@cipherbox/crypto';
  3→import { Modal } from '../ui/Modal';
  4→import { useFolderStore, type FolderNode } from '../../stores/folder.store';
  5→import { getDepth, isDescendantOf } from '../../services/folder.service';
  6→import '../../styles/dialogs.css';
  7→
  8→/** Maximum folder nesting depth per FOLD-03 */
  9→const MAX_FOLDER_DEPTH = 20;
 10→
 11→type MoveDialogProps = {
 12→  /** Whether the dialog is open */
 13→  open: boolean;
 14→  /** Callback when dialog is closed */
 15→  onClose: () => void;
 16→  /** Callback when move is confirmed with destination folder ID */
 17→  onConfirm: (destinationFolderId: string) => void;
 18→  /** The item being moved (single-item mode) */
 19→  item: FolderChild | null;
 20→  /** Multiple items being moved (batch mode — takes precedence over item) */
 21→  items?: FolderChild[];
 22→  /** Current parent folder ID of the item(s) */
 23→  currentFolderId: string;
 24→  /** Loading state - disables buttons */
 25→  isLoading?: boolean;
 26→};
 27→
 28→type FolderListItem = {
 29→  id: string;
 30→  name: string;
 31→  depth: number;
 32→  isDisabled: boolean;
 33→  disabledReason?: string;
 34→};
 35→
 36→/**
 37→ * Build a flat list of folders for the move dialog.
 38→ * Includes root + all loaded subfolders with depth information.
 39→ * Supports multiple items being moved (batch mode).
 40→ */
 41→function buildFolderList(
 42→  folders: Record<string, FolderNode>,
 43→  items: FolderChild[],
 44→  currentFolderId: string
 45→): FolderListItem[] {
 46→  const result: FolderListItem[] = [];
 47→  const folderItemIds = new Set(items.filter((i) => i.type === 'folder').map((i) => i.id));
 48→  const hasFolders = folderItemIds.size > 0;
 49→
 50→  // Add root folder
 51→  const rootFolder = folders['root'];
 52→  if (rootFolder) {
 53→    const isCurrentFolder = currentFolderId === 'root';
 54→
 55→    result.push({
 56→      id: 'root',
 57→      name: 'My Vault',
 58→      depth: 0,
 59→      isDisabled: isCurrentFolder,
 60→      disabledReason: isCurrentFolder ? 'Items are already here' : undefined,
 61→    });
 62→  }
 63→
 64→  // Build sorted list of all folders (excluding root)
 65→  const folderEntries = Object.values(folders).filter((f) => f.id !== 'root');
 66→
 67→  // Sort by depth then name for predictable display
 68→  folderEntries.sort((a, b) => {
 69→    const depthA = getDepth(a.id, folders);
 70→    const depthB = getDepth(b.id, folders);
 71→    if (depthA !== depthB) return depthA - depthB;
 72→    return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
 73→  });
 74→
 75→  for (const folder of folderEntries) {
 76→    const depth = getDepth(folder.id, folders);
 77→    let isDisabled = false;
 78→    let disabledReason: string | undefined;
 79→
 80→    // Disable if this is the current folder
 81→    if (folder.id === currentFolderId) {
 82→      isDisabled = true;
 83→      disabledReason = 'Items are already here';
 84→    }
 85→    // Disable if moving to self (for any folder in the batch)
 86→    else if (folderItemIds.has(folder.id)) {
 87→      isDisabled = true;
 88→      disabledReason = "Can't move folder into itself";
 89→    }
 90→    // Disable if destination is a descendant of any folder being moved
 91→    else if (hasFolders) {
 92→      for (const folderId of folderItemIds) {
 93→        if (isDescendantOf(folder.id, folderId, folders)) {
 94→          isDisabled = true;
 95→          disabledReason = "Can't move folder into its subfolder";
 96→          break;
 97→        }
 98→      }
 99→      // Disable if depth would exceed limit for any folder in the batch
100→      if (!isDisabled) {
101→        if (depth >= MAX_FOLDER_DEPTH - 1) {
102→          isDisabled = true;
103→          disabledReason = 'Would exceed maximum folder depth';
104→        }
105→      }
106→    }
107→
108→    result.push({
109→      id: folder.id,
110→      name: folder.name,
111→      depth,
112→      isDisabled,
113→      disabledReason,
114→    });
115→  }
116→
117→  return result;
118→}
119→
120→/**
121→ * Check if any items' names collide with existing children in the destination.
122→ * Returns the first colliding name, or null if no collisions.
123→ */
124→function checkNameCollisions(
125→  destFolder: FolderNode | undefined,
126→  items: FolderChild[]
127→): string | null {
128→  if (!destFolder) return null;
129→  const itemIds = new Set(items.map((i) => i.id));
130→  for (const item of items) {
131→    const collision = destFolder.children.some(
132→      (child) => child.name === item.name && !itemIds.has(child.id)
133→    );
134→    if (collision) return item.name;
135→  }
136→  return null;
137→}
138→
139→/**
140→ * Dialog for moving files and folders to a different location.
141→ *
142→ * Shows a scrollable list of available folders with depth-based indentation.
143→ * Disables invalid targets (current location, self, descendants).
144→ *
145→ * @example
146→ * ```tsx
147→ * function FileBrowser() {
148→ *   const [moveItem, setMoveItem] = useState<FolderChild | null>(null);
149→ *
150→ *   return (
151→ *     <MoveDialog
152→ *       open={!!moveItem}
153→ *       onClose={() => setMoveItem(null)}
154→ *       onConfirm={(destId) => handleMove(destId)}
155→ *       item={moveItem}
156→ *       currentFolderId={currentFolderId}
157→ *     />
158→ *   );
159→ * }
160→ * ```
161→ */
162→export function MoveDialog({
163→  open,
164→  onClose,
165→  onConfirm,
166→  item,
167→  items: itemsProp,
168→  currentFolderId,
169→  isLoading = false,
170→}: MoveDialogProps) {
171→  const [selectedFolderId, setSelectedFolderId] = useState<string | null>(null);
172→  const [error, setError] = useState<string | null>(null);
173→
174→  // Derive resolved items array: batch prop takes precedence, else single item
175→  const resolvedItems = useMemo(() => {
176→    if (itemsProp && itemsProp.length > 0) return itemsProp;
177→    if (item) return [item];
178→    return [];
179→  }, [itemsProp, item]);
180→
181→  const isBatch = resolvedItems.length > 1;
182→
183→  // Get folders from store
184→  const folders = useFolderStore((state) => state.folders);
185→
186→  // Build folder list
187→  const folderList = useMemo(() => {
188→    if (resolvedItems.length === 0) return [];
189→    return buildFolderList(folders, resolvedItems, currentFolderId);
190→  }, [folders, resolvedItems, currentFolderId]);
191→
192→  // Reset selection when dialog opens
193→  useEffect(() => {
194→    if (open) {
195→      setSelectedFolderId(null);
196→      setError(null);
197→    }
198→  }, [open]);
199→
200→  // Validate selection
201→  const validate = useCallback((): string | null => {
202→    if (!selectedFolderId) {
203→      return 'Please select a destination folder';
204→    }
205→
206→    if (resolvedItems.length === 0) {
207→      return 'No items selected';
208→    }
209→
210→    const selectedItem = folderList.find((f) => f.id === selectedFolderId);
211→    if (selectedItem?.isDisabled) {
212→      return selectedItem.disabledReason ?? 'Invalid destination';
213→    }
214→
215→    // Check for name collisions across all items
216→    const destFolder = folders[selectedFolderId];
217→    const collidingName = checkNameCollisions(destFolder, resolvedItems);
218→    if (collidingName) {
219→      return `An item named "${collidingName}" already exists in the destination`;
220→    }
221→
222→    return null;
223→  }, [selectedFolderId, resolvedItems, folderList, folders]);
224→
225→  const handleSubmit = useCallback(() => {
226→    const validationError = validate();
227→    if (validationError) {
228→      setError(validationError);
229→      return;
230→    }
231→
232→    if (selectedFolderId && !isLoading) {
233→      onConfirm(selectedFolderId);
234→    }
235→  }, [validate, selectedFolderId, isLoading, onConfirm]);
236→
237→  const handleCancel = useCallback(() => {
238→    if (!isLoading) {
239→      onClose();
240→    }
241→  }, [isLoading, onClose]);
242→
243→  const handleSelectFolder = useCallback(
244→    (folderId: string) => {
245→      const folderItem = folderList.find((f) => f.id === folderId);
246→      if (folderItem && !folderItem.isDisabled) {
247→        setSelectedFolderId(folderId);
248→        // Clear error when selecting a new folder
249→        if (error) {
250→          setError(null);
251→        }
252→      }
253→    },
254→    [folderList, error]
255→  );
256→
257→  const handleKeyDown = useCallback(
258→    (event: KeyboardEvent, folderId: string) => {
259→      if (event.key === 'Enter' || event.key === ' ') {
260→        event.preventDefault();
261→        handleSelectFolder(folderId);
262→      }
263→    },
264→    [handleSelectFolder]
265→  );
266→
267→  const title = isBatch
268→    ? `Move ${resolvedItems.length} Items`
269→    : resolvedItems[0]?.type === 'folder'
270→      ? 'Move Folder'
271→      : 'Move File';
272→  const label = isBatch
273→    ? `Move ${resolvedItems.length} selected items to:`
274→    : `Move "${resolvedItems[0]?.name}" to:`;
275→  const isValid = !validate();
276→
277→  return (
278→    <Modal open={open} onClose={handleCancel} title={title}>
279→      <div className="dialog-content">
280→        <div className="dialog-field">
281→          <label className="dialog-label">{label}</label>
282→          <div className="move-dialog-folder-list" role="listbox" aria-label="Select destination">
283→            {folderList.length === 0 && (
284→              <div className="move-dialog-empty">No folders available</div>
285→            )}
286→            {folderList.map((folder) => (
287→              <div
288→                key={folder.id}
289→                className={`move-dialog-folder-item ${
290→                  selectedFolderId === folder.id ? 'move-dialog-folder-item--selected' : ''
291→                } ${folder.isDisabled ? 'move-dialog-folder-item--disabled' : ''}`}
292→                style={{ paddingLeft: `${12 + folder.depth * 16}px` }}
293→                onClick={() => handleSelectFolder(folder.id)}
294→                onKeyDown={(e) => handleKeyDown(e, folder.id)}
295→                role="option"
296→                aria-selected={selectedFolderId === folder.id}
297→                aria-disabled={folder.isDisabled}
298→                tabIndex={folder.isDisabled ? -1 : 0}
299→                title={folder.disabledReason}
300→              >
301→                <span className="move-dialog-folder-icon">[DIR]</span>
302→                <span className="move-dialog-folder-name">{folder.name}</span>
303→              </div>
304→            ))}
305→          </div>
306→          {error && <span className="dialog-error">{error}</span>}
307→        </div>
308→        <div className="dialog-actions">
309→          <button
310→            type="button"
311→            className="dialog-button dialog-button--secondary"
312→            onClick={handleCancel}
313→            disabled={isLoading}
314→          >
315→            Cancel
316→          </button>
317→          <button
318→            type="button"
319→            className="dialog-button dialog-button--primary"
320→            onClick={handleSubmit}
321→            disabled={isLoading || !isValid}
322→          >
323→            {isLoading ? 'Moving...' : 'Move'}
324→          </button>
325→        </div>
326→      </div>
327→    </Modal>
328→  );
329→}
