 44→export function CreateFolderDialog({
 45→  open,
 46→  onClose,
 47→  onConfirm,
 48→  isLoading = false,
 49→}: CreateFolderDialogProps) {
 50→  const [name, setName] = useState('');
 51→  const [error, setError] = useState<string | null>(null);
 52→  const inputRef = useRef<HTMLInputElement>(null);
 53→
 54→  // Reset form when dialog opens
 55→  useEffect(() => {
 56→    if (open) {
 57→      setName('');
 58→      setError(null);
 59→      // Focus input after render
 60→      setTimeout(() => {
 61→        inputRef.current?.focus();
 62→      }, 0);
 63→    }
 64→  }, [open]);
 65→
 66→  const validate = (value: string): string | null => {
 67→    const trimmed = value.trim();
 68→    if (!trimmed) {
 69→      return 'Name cannot be empty';
 70→    }
 71→    // Check for invalid characters (basic)
 72→    if (/[/\\:*?"<>|]/.test(trimmed)) {
 73→      return 'Name contains invalid characters';
 74→    }
 75→    return null;
 76→  };
 77→
 78→  const handleSubmit = useCallback(
 79→    (e: FormEvent) => {
 80→      e.preventDefault();
 81→      const validationError = validate(name);
 82→      if (validationError) {
 83→        setError(validationError);
 84→        return;
 85→      }
 86→      if (!isLoading) {
 87→        onConfirm(name.trim());
 88→      }
 89→    },
 90→    [name, isLoading, onConfirm]
 91→  );
 92→
 93→  const handleCancel = useCallback(() => {
 94→    if (!isLoading) {
 95→      onClose();
 96→    }
 97→  }, [isLoading, onClose]);
 98→
 99→  const handleChange = (value: string) => {
100→    setName(value);
101→    // Clear error when user starts typing
102→    if (error) {
103→      setError(null);
104→    }
105→  };
106→
107→  return (
