109→      <form className="dialog-content" onSubmit={handleSubmit}>
110→        <div className="dialog-field">
111→          <label htmlFor="folder-name-input" className="dialog-label">
112→            Folder name
113→          </label>
114→          <input
115→            ref={inputRef}
116→            id="folder-name-input"
117→            type="text"
118→            className={`dialog-input ${error ? 'dialog-input--error' : ''}`}
119→            value={name}
120→            onChange={(e) => handleChange(e.target.value)}
121→            disabled={isLoading}
122→            autoComplete="off"
123→            spellCheck={false}
124→            placeholder="Enter folder name"
125→          />
126→          {error && <span className="dialog-error">{error}</span>}
127→        </div>
128→        <div className="dialog-actions">
129→          <button
130→            type="button"
131→            className="dialog-button dialog-button--secondary"
132→            onClick={handleCancel}
133→            disabled={isLoading}
134→          >
135→            Cancel
136→          </button>
137→          <button
138→            type="submit"
139→            className="dialog-button dialog-button--primary"
140→            disabled={isLoading || !!validate(name)}
141→          >
142→            {isLoading ? 'Creating...' : 'Create'}
143→          </button>
144→        </div>
145→      </form>
146→    </Modal>
147→  );
148→}
